import{_ as t,o as a,c as i,a2 as l}from"./chunks/framework.Cd7uensT.js";const r="/idc_assest-docs/images/screenshots/idle-device-management.png",p=JSON.parse('{"title":"空闲设备管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features/idle-device-management.md","filePath":"guide/features/idle-device-management.md","lastUpdated":1785486863000}'),o={name:"guide/features/idle-device-management.md"};function d(n,e,s,h,c,m){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="空闲设备管理" tabindex="-1">空闲设备管理 <a class="header-anchor" href="#空闲设备管理" aria-label="Permalink to &quot;空闲设备管理&quot;">​</a></h1><p>空闲设备管理用于管理当前未上架或暂时不使用的设备。</p><p><img src="'+r+'" alt="空闲设备管理概览"></p><blockquote><p><strong>v2.2.0 更新</strong>：新增空闲设备列表与详情展示页面，支持按资产编号、设备名称、设备型号搜索筛选；移除表单中的资产状态和入库日期字段，优化数据录入体验。</p></blockquote><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><ul><li>查看所有空闲设备列表，支持搜索筛选</li><li>查看空闲设备详情信息</li><li>将运行中设备转入空闲状态</li><li>将空闲设备重新激活上架</li></ul><h2 id="搜索筛选" tabindex="-1">搜索筛选 <a class="header-anchor" href="#搜索筛选" aria-label="Permalink to &quot;搜索筛选&quot;">​</a></h2><p>v2.2.0 新增，支持多维度快速查找空闲设备：</p><table tabindex="0"><thead><tr><th>筛选条件</th><th>说明</th></tr></thead><tbody><tr><td><strong>资产编号</strong></td><td>按设备资产编号精确/模糊搜索</td></tr><tr><td><strong>设备名称</strong></td><td>按设备名称关键词搜索</td></tr><tr><td><strong>设备型号</strong></td><td>按设备型号关键词搜索</td></tr></tbody></table><p>操作方式：在空闲设备列表页顶部的搜索栏中输入关键词，点击「搜索」按钮或按回车键即可筛选结果。</p><h2 id="操作流程" tabindex="-1">操作流程 <a class="header-anchor" href="#操作流程" aria-label="Permalink to &quot;操作流程&quot;">​</a></h2><h3 id="设备转入空闲" tabindex="-1">设备转入空闲 <a class="header-anchor" href="#设备转入空闲" aria-label="Permalink to &quot;设备转入空闲&quot;">​</a></h3><ol><li>在设备管理页面，选择需要转入空闲的设备</li><li>点击「转入空闲」按钮</li><li>确认操作后，设备状态变为空闲</li><li>在「空闲设备」页面查看所有空闲设备</li></ol><h3 id="空闲设备激活" tabindex="-1">空闲设备激活 <a class="header-anchor" href="#空闲设备激活" aria-label="Permalink to &quot;空闲设备激活&quot;">​</a></h3><ol><li>进入「空闲设备」页面</li><li>通过搜索筛选找到目标设备</li><li>点击设备行进入详情页查看完整信息</li><li>确认无误后点击「激活」按钮</li><li>填写上架信息（机房、机柜、U位等）后提交，设备恢复为运行状态</li></ol>',15)])])}const _=t(o,[["render",d]]);export{p as __pageData,_ as default};
